#include <stdio.h>
#include <math.h>
#include <stdlib.h>

// Test vector structure
typedef struct {
    char id[16];
    float Valpha;
    float Vbeta;
    int expected_sector;
    int expected_duty_u;
    int expected_duty_v;
    int expected_duty_w;
} TestCase_t;

// Sector lookup table (sector determination)
static const int sector_table[7] = {0, 2, 6, 1, 4, 3, 5};

int determine_sector(float Valpha, float Vbeta) {
    float Vref1 = Vbeta;
    float Vref2 = (sqrtf(3.0) * Valpha - Vbeta) / 2.0f;
    float Vref3 = (-sqrtf(3.0) * Valpha - Vbeta) / 2.0f;

    int A = (Vref1 > 0.0f) ? 1 : 0;
    int B = (Vref2 > 0.0f) ? 1 : 0;
    int C = (Vref3 > 0.0f) ? 1 : 0;

    int N = 4 * C + 2 * B + A;

    if (N < 1 || N > 6) return 1; /* fallback */
    return sector_table[N];
}

int main() {
    FILE *fp = fopen("test_vectors.csv", "r");
    if (!fp) {
        printf("ERROR: Cannot open test_vectors.csv\n");
        return 1;
    }

    TestCase_t *cases = malloc(100 * sizeof(TestCase_t));
    int count = 0;
    char line[256];

    // Skip header
    fgets(line, sizeof(line), fp);

    while (fgets(line, sizeof(line), fp)) {
        if (count >= 100) break;
        char *token = strtok(line, ",\n");
        cases[count].id = token;
        token = strtok(NULL, ",\n");
        cases[count].Valpha = atof(token);
        token = strtok(NULL, ",\n");
        cases[count].Vbeta = atof(token);
        token = strtok(NULL, ",\n");
        cases[count].expected_sector = atoi(token);
        token = strtok(NULL, ",\n");
        cases[count].expected_duty_u = atoi(token);
        token = strtok(NULL, ",\n");
        cases[count].expected_duty_v = atoi(token);
        token = strtok(NULL, ",\n");
        cases[count].expected_duty_w = atoi(token);
        count++;
    }
    fclose(fp);

    printf("Testing %d cases:\n", count);

    double sqrt3 = sqrt(3.0);
    double K = sqrt3 * 500.0 / 310.0;  // K = sqrt(3) * PWM_HALF_PERIOD / VDC

    int pass = 0;
    for (int i = 0; i < count; i++) {
        float Valpha = cases[i].Valpha;
        float Vbeta = cases[i].Vbeta;

        int sector = determine_sector(Valpha, Vbeta);

        // Calculate X, Y, Z intermediate values
        float X = K * Vbeta;
        float Y = K * (sqrt3 * 0.5f * Valpha + 0.5f * Vbeta);
        float Z = K * (-sqrt3 * 0.5f * Valpha + 0.5f * Vbeta);

        float T1, T2;

        switch (sector) {
