            case 6: T1 = -Z; T2 =  Y; break;
            default: T1 = 0; T2 = 0; break;
        }

        // Clamp to linear range
        if (T1 + T2 > 500.0) {
            float scale = 500.0 / (T1 + T2);
            T1 *= scale;
            T2 *= scale;
        }

        float T0 = 500.0 - T1 - T2;

