                Tu = 500 + (int)(T1 + T0/4.0);
                Tv = 500 + (int)(T1 + T2 + T0/4.0);
                Tw = 500 + (int)(T0/4.0);
                break;
            case 3:
                // U: T0/4, V: T1 + T2 + T0/4, W: T2 + T0/4
                Tu = 500 + (int)(T0/4.0);
                Tv = 500 + (int)(T1 + T2 + T0/4.0);
                Tw = 500 + (int)(T2 + T0/4.0);
                break;
            case 4:
                // U: T0/4, V: T1 + T0/4, W: T1 + T2 + T0/4
                Tu = 500 + (int)(T0/4.0);
                Tv = 500 + (int)(T1 + T0/4.0);
                Tw = 500 + (int)(T1 + T2 + T0/4.0);
                break;
            case 5:
                // U: T2 + T0/4, V: T0/4, W: T1 + T2 + T0/4
                Tu = 500 + (int)(T2 + T0/4.0);
                Tv = 500 + (int)(T0/4.0);
                Tw = 500 + (int)(T1 + T2 + T0/4.0);
                break;
            case 6:
                // U: T1 + T2 + T0/4, V: T0/4, W: T2 + T0/4
                Tu = 500 + (int)(T1 + T2 + T0/4.0);
                Tv = 500 + (int)(T0/4.0);
                Tw = 500 + (int)(T2 + T0/4.0);
                break;
            default:
                Tu = Tv = Tw = 500;
                break;
        }

        // Clamp to range [0, 1000]
        if (Tu < 0) Tu = 0;
        if (Tu > 1000) Tu = 1000;
        if (Tv < 0) Tv = 0;
        if (Tv > 1000) Tv = 1000;
        if (Tw < 0) Tw = 0;
        if (Tw > 1000) Tw = 1000;

