                // U: T0/4, V: T1 + T2 + T0/4, W: T2 + T0/4
                Tu = 500 + (int)(T0/4.0);
                Tv = 500 + (int)(T1 + T2 + T0/4.0);
                Tw = 500 + (int)(T2 + T0/4.0);
                break;
            case 4:
                // U: T0/4, V: T1 + T0/4, W: T1 + T2 + T0/4
                Tu = 500 + (int)(T0/4.0);
                Tv = 500 + (int)(T1 + T0/4.0);
                Tw = 500 + (int)(T1 + T2 + T0/4.0);
                break;
            case 5:
                // U: T2 + T0/4, V: T0/4, W: T1 + T2 + T0/4
                Tu = 500 + (int)(T2 + T0/4.0);
                Tv = 500 + (int)(T0/4.0);
                Tw = 500 + (int)(T1 + T2 + T0/4.0);
                break;
            case 6:
                // U: T1 + T2 + T0/4, V: T0/4, W: T2 + T0/4
                Tu = 500 + (int)(T1 + T2 + T0/4.0);
                Tv = 500 + (int)(T0/4.0);
                Tw = 500 + (int)(T2 + T0/4.0);
                break;
            default:
                Tu = Tv = Tw = 500;
                break;
        }

        // Clamp to range [0, 1000]
        if (Tu < 0) Tu = 0;
        if (Tu > 1000) Tu = 1000;
        if (Tv < 0) Tv = 0;
        if (Tv > 1000) Tv = 1000;
        if (Tw < 0) Tw = 0;
        if (Tw > 1000) Tw = 1000;

        int status = 0;
        if (sector != cases[i].expected_sector) {
            printf("FAIL %s: sector=%d, expected=%d\n", cases[i].id, sector, cases[i].expected_sector);
            status |= 1;
        }
        if (Tu != cases[i].expected_duty_u) {
            printf("FAIL %s: u=%d, expected=%d\n", cases[i].id, Tu, cases[i].expected_duty_u);
            status |= 2;
        }
        if (Tv != cases[i].expected_duty_v) {
            printf("FAIL %s: v=%d, expected=%d\n", cases[i].id, Tv, cases[i].expected_duty_v);
            status |= 4;
        }
        if (Tw != cases[i].expected_duty_w) {
            printf("FAIL %s: w=%d, expected=%d\n", cases[i].id, Tw, cases[i].expected_duty_w);
            status |= 8;
        }

        printf("PASS %s: sector=%d, u=%d, v=%d, w=%d\n", cases[i].id, sector, Tu, Tv, Tw);
        if (status == 0) pass++;
    }

    printf("\n%d/%d tests passed\n", pass, count);

    return (pass == count) ? 0 : 1;
}
